import {readFileSync} from 'node:fs';
import {hash} from '../store.mjs';
import {buildEnterpriseValueImpact} from '../assurance/enterprise-value-impact.mjs';
import {htmlTableProofs,bindRawTable,normalizeCell} from '../p02/source-proof.mjs';
export const PERIOD={start:'2024-01-01',end:'2025-12-31',asOf:'2025-12-31',years:[2025,2024]};
export const CRITERIA='p07-financial-risk-1';
export const NAMES={'005930':'삼성전자','000660':'SK하이닉스'};
export const PARAMETERS={scope:'CFS',currency:'KRW',unit:'백만원',amounts:'signed integer BigInt',ratios:'percent; two decimal places; truncate toward zero',cashBridge:'source hierarchy; avoid double counting generated subtotal',cashRemainder:'CFO - PPE acquisition outflow - intangible acquisition outflow; not FCFF',forecast:'held; two annual observations, no point-in-time training data',valuation:'held; WACC/g/net-debt/diluted shares/FCFF mapping not secured'};
export const LIMITS=['2025 사업보고서의 2024·2025 연결 기준 비교입니다. 발표일은 2026-03-10/03-17이며 당시 이용 가능 자료 이력·최신/정정 탐색은 미확보입니다.',
 '삼성은 전 사업 연결, SK는 해당 연결 범위입니다. 기업 규모·사업 구성·회계 분류가 달라 금액·비율만으로 효율·경쟁력·위험의 우열을 판정하지 않습니다.',
 '영업현금흐름(CFO), 영업에서 창출된 현금, 당기순이익, 영업이익은 서로 다른 계정입니다. 회계 합산 일치는 사업상의 원인·지속성을 인증하지 않습니다.',
 '유형·무형자산 취득 지출을 CFO에서 뺀 잔액은 좁은 현금 산식입니다. 이자·세금·리스·사업결합·재투자 정의를 조정한 FCFF/FCFE가 아닙니다.',
 '유동비율·부채/자본과 재고 금액은 관측 지표입니다. 만기·질·우발부채·시장/신용 위험의 확률·손실액을 인증하지 않습니다. 위험관리 문장은 회사의 공시 설명입니다.',
 '두 연간 관측만으로 ML/DL 예측을 학습하지 않습니다. 할인율·장기성장·순차입금·희석주식·FCFF 계보가 미확보여서 DCF·적정가치·저평가·목표가·매매 판단을 보류합니다.',
 'AI 자유설명은 의미 미검증 초안입니다. 개인 확인은 공동 승인·발행이 아닙니다.'];
const fail=s=>{throw Error('P07 '+s);};
export function integer(s){s=String(s).trim();if(!/^(?:-?(?:\d{1,3}(?:,\d{3})*|\d+)|\((?:\d{1,3}(?:,\d{3})*|\d+)\))$/.test(s))fail('금액 형식·결측');return BigInt(s.replaceAll(',','').replace(/^\((.*)\)$/,'-$1'));}
export function percent(n,d){n=BigInt(n);d=BigInt(d);if(d<=0n)return null;const q=n*10000n/d,a=q<0n?-q:q;return (q<0n?'-':'')+(a/100n)+'.'+String(a%100n).padStart(2,'0');}
const matching=(t,re)=>{const rs=t.rows.filter(r=>re.test(r.cells[0]));if(rs.length!==1)fail('항목 매핑 '+re);return rs[0];};
const entry=(t,re,col)=>{const r=matching(t,re);return {tableId:t.id,row:r.row,label:r.cells[0],sourceValue:r.cells[col],value:String(integer(r.cells[col])),column:col,year:PERIOD.years[col-1],currency:'KRW',unit:'백만원',scope:'CFS',periodStart:t.id.endsWith('-t2')?null:PERIOD.years[col-1]+'-01-01',periodEnd:PERIOD.years[col-1]+'-12-31',periodType:t.id.endsWith('-t2')?'instant':'duration',rawTableProof:t.rawTableProof};};
export function loadFinancialCorpus(){
 const path=new URL('../../sources/p07/',import.meta.url),manifest=JSON.parse(readFileSync(new URL('manifest.json',path)));if(hash(JSON.stringify(manifest.files))!==manifest.digest)fail('manifest');
 for(const f of manifest.files)if(!/^[\w.-]+$/.test(f.file)||hash(readFileSync(new URL(f.file,path)))!==f.hash)fail('원문 파일 해시');
 const corpus=JSON.parse(readFileSync(new URL('corpus.json',path)));
 const documents=corpus.documents.map(d=>{if(!NAMES[d.company]||d.rcpNo!==({'005930':'20260310002820','000660':'20260317000635'})[d.company]||!d.url.startsWith('https://dart.fss.or.kr/report/viewer.do?rcpNo='+d.rcpNo)||!d.title.includes('2025'))fail('회사·공시·연도');const bytes=readFileSync(new URL(d.rawFile,path));if(hash(bytes)!==d.rawHash||d.liveCheck.sha256!==d.rawHash||d.liveCheck.status!==200||!d.liveCheck.matchesStoredBytes)fail('공식 원문 바이트');const proofs=htmlTableProofs(bytes),tables=d.tables.map(t=>{if(t.company!==d.company||t.documentId!==d.id)fail('표 회사·문서');return bindRawTable(t,proofs);});
  const text=normalizeCell(bytes.toString('utf8'));for(const q of d.paragraphs)if(q.company!==d.company||q.documentId!==d.id||hash(q.excerpt)!==q.excerptHash||!text.includes(normalizeCell(q.excerpt)))fail('위험 직접인용');
  if(d.scope==='CFS'){if(tables.length!==6)fail('재무 표 6개');const headers=tables.filter(t=>/연결 (?:재무상태|.*손익|현금흐름)/.test(t.rows[0].cells[0]));if(headers.length!==3||headers.some(t=>!JSON.stringify(t.rows).includes('2025')||!JSON.stringify(t.rows).includes('2024')||!JSON.stringify(t.rows).includes('백만원')))fail('기간·단위 표 머리글');const seq=d.company==='005930'?['제 57 기','제 56 기']:['제 78 기','제 77 기'];for(const t of tables.filter(t=>t.rows[0].cells[0]===''))if(JSON.stringify(t.rows[0].cells.slice(1,3))!==JSON.stringify(seq))fail('연도 열 순서');}
  return {...d,tables,rawResponse:bytes.toString('utf8'),asOf:PERIOD.asOf};});
 const sources=Object.entries(NAMES).map(([id,name])=>{const docs=documents.filter(d=>d.company===id);if(docs.length!==2||docs.filter(d=>d.scope==='CFS').length!==1)fail('재무·위험 문서');const financial=docs.find(d=>d.scope==='CFS'),risk=docs.find(d=>d.scope!=='CFS');if(!risk.paragraphs.length)fail('위험 원문');return {id,company:id,name,documents:docs,rawHash:hash(JSON.stringify(docs.map(d=>d.rawHash))),url:financial.url,financialId:financial.id,paragraphs:risk.paragraphs,history:PERIOD,scope:'2024·2025 연결 재무상태·손익·현금흐름과 2025 위험관리 문단',facts:corpus.facts.filter(f=>f.company===id),checkedAt:docs.map(d=>d.checkedAt).sort().at(-1)};});
 return {sources,digest:hash(JSON.stringify(sources)),manifestDigest:manifest.digest};
}
export function calculateFinancial(s){
 const doc=s.documents.find(d=>d.id===s.financialId),table=n=>{const t=doc.tables.find(t=>t.id.endsWith('-t'+n));if(!t)fail('표 누락');return t;},balance=table(2),income=table(4),cash=table(s.id==='005930'?10:8),years=[];
 for(const [i,year] of PERIOD.years.entries()){const col=i+1,inputs={revenue:entry(income,/^매출액(?: |$)/,col),operatingProfit:entry(income,/^영업이익(?:\(손실\))?(?: |$)/,col),cfo:entry(cash,/^영업활동\s*현금흐름$/,col),currentAssets:entry(balance,/^유동자산$/,col),currentLiabilities:entry(balance,/^유동부채$/,col),assets:entry(balance,/^자산총계$/,col),liabilities:entry(balance,/^부채총계$/,col),equity:entry(balance,/^자본총계$/,col),inventory:entry(balance,/^재고자산(?: |$)/,col),ppeAcquisition:entry(cash,/^유형자산의 취득$/,col),intangibleAcquisition:entry(cash,/^무형자산의 취득$/,col)},v=k=>BigInt(inputs[k].value);
  for(const [metric,key] of [['revenue','revenue'],['operatingProfit','operatingProfit'],['operatingCashFlow','cfo']]){const f=s.facts.find(f=>f.metric===metric&&f.year===year);if(!f||f.value!==inputs[key].value||f.scope!=='CFS'||f.currency!=='KRW'||f.unit!=='백만원')fail('독립 저장 계정 대조');}
  if(v('assets')!==v('liabilities')+v('equity')||v('ppeAcquisition')>0n||v('intangibleAcquisition')>0n)fail('재무등식·지출 부호');
  const opEnd=cash.rows.findIndex(r=>/^투자활동/.test(r.cells[0])),op=cash.rows.slice(1,opEnd),generated=op.find(r=>/영업에서 창출|영업으로부터 창출/.test(r.cells[0]));if(!generated)fail('영업창출현금');const after=op.slice(op.indexOf(generated)+1),net=after.find(r=>/^당기순이익/.test(r.cells[0])),adjust=after.find(r=>/^조정/.test(r.cells[0])),wc=after.find(r=>/^영업활동으로 인한 자산부채/.test(r.cells[0]));
  const rows=net&&adjust&&wc?[net,adjust,wc,...after.slice(after.indexOf(wc)+1)]:[generated,...after],components=rows.map(r=>({tableId:cash.id,row:r.row,label:r.cells[0],sourceValue:r.cells[col],value:String(integer(r.cells[col]))}));const total=components.reduce((n,r)=>n+BigInt(r.value),0n);if(total!==v('cfo'))fail('CFO 합산');if(net&&integer(net.cells[col])+integer(adjust.cells[col])+integer(wc.cells[col])!==integer(generated.cells[col]))fail('영업창출현금 소계');
  const acquisitions=-v('ppeAcquisition')-v('intangibleAcquisition');years.push({year,unit:'백만원',currency:'KRW',scope:'CFS',inputs,revenue:inputs.revenue.value,operatingProfit:inputs.operatingProfit.value,cfo:inputs.cfo.value,operatingMargin:percent(v('operatingProfit'),v('revenue')),cfoMargin:percent(v('cfo'),v('revenue')),currentRatio:percent(v('currentAssets'),v('currentLiabilities')),debtToEquity:percent(v('liabilities'),v('equity')),inventory:inputs.inventory.value,acquisitionOutflow:String(acquisitions),cashRemainder:String(v('cfo')-acquisitions),profitCfoGap:String(v('cfo')-v('operatingProfit')),bridge:{tableId:cash.id,start:components[0].label,components,sum:String(total),cfo:inputs.cfo.value,residual:'0',generatedCash:String(integer(generated.cells[col])),nestedSubtotalChecked:!!net,netIncome:net?String(integer(net.cells[col])):null,operatingProfitToStartGap:net?String(integer(net.cells[col])-v('operatingProfit')):String(integer(generated.cells[col])-v('operatingProfit')),limit:net?'순이익+조정+운전자본변동과 이자·배당·세금. 조정/운전자본 세부 주석은 추가 미조회.':'영업창출현금부터 연결. 순이익·조정·운전자본 세부 주석 미조회; 영업이익에서 창출현금으로의 차이 원인 미분해.'}});
 }
 const [a,b]=years,changes={revenue:String(BigInt(a.revenue)-BigInt(b.revenue)),operatingProfit:String(BigInt(a.operatingProfit)-BigInt(b.operatingProfit)),cfo:String(BigInt(a.cfo)-BigInt(b.cfo)),inventory:String(BigInt(a.inventory)-BigInt(b.inventory)),cashRemainder:String(BigInt(a.cashRemainder)-BigInt(b.cashRemainder)),cfoPercent:percent(BigInt(a.cfo)-BigInt(b.cfo),b.cfo)};
 return {ready:true,period:PERIOD,parameters:PARAMETERS,years,changes,riskQuotes:s.paragraphs.map(q=>({id:q.id,excerpt:q.excerpt,excerptHash:q.excerptHash,locator:q.locator,url:q.url,scope:'회사 공시 위험관리 설명. 독립 위험평가 아님'})),formulas:['영업이익률 = 영업이익 / 매출 × 100','CFO/매출 = CFO / 매출 × 100','유동비율 = 유동자산 / 유동부채 × 100','부채/자본 = 부채총계 / 자본총계 × 100','취득 지출 = -(유형자산 취득 현금흐름 + 무형자산 취득 현금흐름)','좁은 현금 잔액 = CFO - 유형·무형 취득 지출 (FCFF 아님)','증감 = 2025 - 2024; 비율 소수 2자리 0 방향 절삭'],forecast:null,fcff:null,valuation:null,meaningVerified:false};
}
export function makeEvidence(s,action){return action==='calculate_financial'?{id:s.id,company:s.company,name:s.name,kind:'calculation',rawHash:s.rawHash,criteriaVersion:CRITERIA,inputDigest:hash(JSON.stringify({rawHash:s.rawHash,tables:s.documents.map(d=>d.tables),facts:s.facts,period:PERIOD,parameters:PARAMETERS,version:CRITERIA})),calculation:calculateFinancial(s)}:{...s,kind:'source',criteriaVersion:CRITERIA};}
export function validateFinancialEvidence(e){const s=loadFinancialCorpus().sources.find(s=>s.id===e.id);if(!s||JSON.stringify(e)!==JSON.stringify(makeEvidence(s,e.kind==='calculation'?'calculate_financial':'read_financial')))fail('원문·기간·부호·계산 재현');return true;}
export function observeFinancial(s,v,action,reused=false){return action==='read_financial'?{status:'source_read',company:s.id,period:PERIOD,documents:s.documents.map(d=>({section:d.section,scope:d.scope,unit:d.unit,publishedDate:d.publishedDate,rawHash:d.rawHash,checkedAt:d.checkedAt})),cashflowRows:s.documents.find(d=>d.id===s.financialId).tables.at(-1).rows.slice(0,s.id==='005930'?10:7).map(r=>r.cells.slice(0,3)),riskQuotes:s.paragraphs.map(q=>({excerpt:q.excerpt,id:q.id})),message:'실제 표를 읽었습니다. 순이익 조정 vs 영업창출현금 출발점, 이자/세금/취득 지출 정의를 관찰하여 비교계획을 보완하세요. 두 연간 관측만으로 예측/DCF는 보류.',reused}:{status:v.calculation.ready?'calculated':'source_gap',company:s.id,years:v.calculation.years.map(y=>({year:y.year,cfo:y.cfo,operatingProfit:y.operatingProfit,operatingMargin:y.operatingMargin,currentRatio:y.currentRatio,debtToEquity:y.debtToEquity,inventory:y.inventory,acquisitionOutflow:y.acquisitionOutflow,cashRemainder:y.cashRemainder,bridge:y.bridge})),changes:v.calculation.changes,inputDigest:v.inputDigest,message:'CFO 합산·재무등식 잔차0. 취득지출 차감 잔액은 FCFF/가치 아님. 회계연결과 인과·미래 지속성은 구별.',reused};}
export function buildFinancialAnswer(p){const companies=Object.entries(NAMES).map(([id,name])=>{const source=p.evidence.find(e=>e.id===id&&e.kind==='source'),e=p.evidence.find(e=>e.id===id&&e.kind==='calculation');return {id,name,read:!!source,calculated:!!e,calculation:e?.calculation||null,source:source?{url:source.url,documents:source.documents.map(({rawResponse,tables,...d})=>d),rawHash:source.rawHash,asOf:PERIOD.asOf,checkedAt:source.checkedAt}:null};}),trillion=n=>{const v=BigInt(n),neg=v<0n?'-':'',a=v<0n?-v:v;return neg+String(a/1000000n)+'.'+String(a%1000000n/10000n).padStart(2,'0');};const ready=companies.every(c=>c.read&&c.calculation?.ready);return {version:CRITERIA,ready,companies,summary:companies.map(c=>{if(!c.calculation)return c.name+': '+(c.read?'원문 확인, 계산 대기':'원문 읽기 미확보');const a=c.calculation.years[0],b=c.calculation.years[1];return `${c.name}: 2025년 영업현금흐름은 약 ${trillion(a.cfo)}조원으로, 2024년 약 ${trillion(b.cfo)}조원보다 ${trillion(c.calculation.changes.cfo)}조원 증가했습니다. 2025년 유형·무형자산 취득 지출 약 ${trillion(a.acquisitionOutflow)}조원을 뺀 좁은 현금 잔액은 약 ${trillion(a.cashRemainder)}조원입니다. 이 잔액은 FCFF나 기업가치가 아닙니다.`;}),held:[...LIMITS,...(p.gaps||[])],assurance:{adapter:CRITERIA,perspectives:['P01','P02','P03','P04','P05','P06','P07'],meaningVerified:false,publicationApproved:false},forecast:null,valuation:null,valueImpact:buildEnterpriseValueImpact({question:p.question,perspective:'P07',kind:'financial',companies,facts:[]})};}
